#include "geometry_extra_common.hpp"
#include <Eigen/Dense>
#include <array>
#include <functional>
#include <map>
#include <vector>
namespace {
using namespace penta::geometry_extra;
using Matrix=Eigen::Matrix<double,Eigen::Dynamic,Eigen::Dynamic,Eigen::RowMajor>;
std::vector<unsigned> basis(unsigned n,unsigned k){std::vector<unsigned> result;if(k>n)return result;std::function<void(unsigned,unsigned,unsigned)> collect=[&](unsigned start,unsigned remaining,unsigned mask){if(!remaining){result.push_back(mask);return;}for(unsigned axis=start;axis+remaining<=n;++axis)collect(axis+1,remaining-1,mask|(1u<<axis));};collect(0,k,0);return result;}
int sign(unsigned left,unsigned right){unsigned inversions=0;for(unsigned a=0;a<8;++a)if(left&(1u<<a))for(unsigned b=0;b<a;++b)if(right&(1u<<b))++inversions;return inversions%2?-1:1;}
struct Form {
 unsigned n,k,order;bool constant;int orientation;std::vector<unsigned> masks;std::vector<double> value,first,second;Matrix metric;
 explicit Form(const penta_form_value_v1& input,double tolerance):n(input.dimension),k(input.degree),order(input.derivative_order),constant(input.constant_coefficients!=0),orientation(input.orientation){
    if(n<1||n>8||k>32||order>2||input.constant_coefficients>1||(orientation!=1&&orientation!=-1)||!input.metric)throw Failure(PENTA_NUMERIC_ARGUMENT,"Forms require dimension1..8, bounded degree, order0..2 and explicit orientation+1/-1.");
    if(!std::isfinite(tolerance)||tolerance<=0||tolerance>=.1)throw Failure(PENTA_NUMERIC_ARGUMENT,"Invalid differential-form metric tolerance.");
    masks=basis(n,k);const auto count=masks.size();if(count&&!input.coefficients)throw Failure(PENTA_NUMERIC_ARGUMENT,"Missing differential-form coefficients.");value.assign(count,0);first.assign(count*n,0);second.assign(count*n*n,0);if(count)std::copy_n(input.coefficients,count,value.begin());
    if(order>=1&&count&&!constant){if(!input.first)throw Failure(PENTA_NUMERIC_ARGUMENT,"Missing native coefficient Jacobian.");std::copy_n(input.first,count*n,first.begin());}
    if(order>=2&&count&&!constant){if(!input.second)throw Failure(PENTA_NUMERIC_ARGUMENT,"Missing native coefficient Hessians.");std::copy_n(input.second,count*n*n,second.begin());}
    for(const auto* values:{&value,&first,&second})for(const auto x:*values)if(!std::isfinite(x))throw Failure(PENTA_NUMERIC_ARGUMENT,"Form coefficients/derivatives must be finite.");
    metric=Eigen::Map<const Matrix>(input.metric,n,n);if(!metric.allFinite())throw Failure(PENTA_NUMERIC_ARGUMENT,"The form metric must be finite.");const double scale=metric.cwiseAbs().maxCoeff();if(scale==0)throw Failure(PENTA_NUMERIC_ARGUMENT,"The form metric must be positive definite.");const Matrix reduced=metric/scale;if((reduced-reduced.transpose()).norm()>tolerance*reduced.norm())throw Failure(PENTA_NUMERIC_ARGUMENT,"The form metric must be a symmetric real matrix.");Eigen::SelfAdjointEigenSolver<Matrix> eigen(reduced,Eigen::EigenvaluesOnly);if(eigen.info()!=Eigen::Success||eigen.eigenvalues()[0]<=tolerance*eigen.eigenvalues()[n-1])throw Failure(PENTA_NUMERIC_ARGUMENT,"The form metric must be positive definite and numerically nonsingular.");
 }
};
int forms(const penta_geometry_extra_host_v1* host,const penta_form_request_v1* request,penta_form_result_v1* result,char* error,uint64_t capacity)noexcept{
 try{
    validateHost(host);if(!request||request->struct_size<sizeof(*request)||!result||result->struct_size<sizeof(*result))throw Failure(PENTA_NUMERIC_VERSION,"Incompatible differential-forms ABI.");Work work{*host,request->max_work};work.check();Form a(request->a,request->tolerance);work.spend(a.n*a.n+a.value.size());unsigned degree=a.k,order=a.order;bool constant=a.constant;std::vector<double> values=a.value,first=a.first,second=a.second;
    if(request->operation==PENTA_FORM_WEDGE){Form b(request->b,request->tolerance);if(a.n!=b.n||a.orientation!=b.orientation||((a.metric-b.metric)/a.metric.cwiseAbs().maxCoeff()).norm()>request->tolerance*(a.metric/a.metric.cwiseAbs().maxCoeff()).norm())throw Failure(PENTA_NUMERIC_ARGUMENT,"Wedge operands require the same coordinate dimension, orientation and declared metric.");degree=a.k+b.k;if(degree>32)throw Failure(7,"Differential-form degree exceeds32.");order=std::min(a.order,b.order);constant=a.constant&&b.constant;const auto output=basis(a.n,degree);std::map<unsigned,std::size_t> indices;for(std::size_t n=0;n<output.size();++n)indices[output[n]]=n;values.assign(output.size(),0);first.assign(output.size()*a.n,0);second.assign(output.size()*a.n*a.n,0);
        for(std::size_t i=0;i<a.masks.size();++i)for(std::size_t j=0;j<b.masks.size();++j){work.spend(a.n*a.n+1);if(a.masks[i]&b.masks[j])continue;const auto out=indices.at(a.masks[i]|b.masks[j]);const double factor=sign(a.masks[i],b.masks[j]);values[out]=finite(static_cast<long double>(values[out])+factor*static_cast<long double>(a.value[i])*b.value[j]);if(order>=1)for(unsigned c=0;c<a.n;++c)first[out*a.n+c]=finite(static_cast<long double>(first[out*a.n+c])+factor*(static_cast<long double>(a.first[i*a.n+c])*b.value[j]+static_cast<long double>(a.value[i])*b.first[j*a.n+c]));if(order>=2)for(unsigned c=0;c<a.n;++c)for(unsigned d=0;d<a.n;++d)second[(out*a.n+c)*a.n+d]=finite(static_cast<long double>(second[(out*a.n+c)*a.n+d])+factor*(static_cast<long double>(a.second[(i*a.n+c)*a.n+d])*b.value[j]+static_cast<long double>(a.first[i*a.n+c])*b.first[j*a.n+d]+static_cast<long double>(a.first[i*a.n+d])*b.first[j*a.n+c]+static_cast<long double>(a.value[i])*b.second[(j*a.n+c)*a.n+d]));}
    }else if(request->operation==PENTA_FORM_D){if(!a.constant&&a.order<1)throw Failure(PENTA_NUMERIC_ARGUMENT,"Exterior derivative needs compiler-generated coefficient derivatives; this pointwise result has no validated derivative adapter.");degree=a.k+1;if(degree>32)throw Failure(7,"Differential-form degree exceeds32.");order=a.constant?2:a.order-1;const auto output=basis(a.n,degree);std::map<unsigned,std::size_t> indices;for(std::size_t i=0;i<a.masks.size();++i)indices[a.masks[i]]=i;values.assign(output.size(),0);first.assign(output.size()*a.n,0);second.assign(output.size()*a.n*a.n,0);for(std::size_t out=0;out<output.size();++out){unsigned position=0;for(unsigned axis=0;axis<a.n;++axis)if(output[out]&(1u<<axis)){work.spend(a.n+1);const auto input=indices.at(output[out]^(1u<<axis));const double factor=position++%2?-1:1;values[out]=finite(static_cast<long double>(values[out])+factor*a.first[input*a.n+axis]);if(order>=1)for(unsigned d=0;d<a.n;++d)first[out*a.n+d]=finite(static_cast<long double>(first[out*a.n+d])+factor*a.second[(input*a.n+axis)*a.n+d]);}}}
    else if(request->operation==PENTA_FORM_HODGE){if(a.k>a.n)throw Failure(PENTA_NUMERIC_ARGUMENT,"Hodge star requires degree0..dimension.");degree=a.n-a.k;const auto output=basis(a.n,degree);const unsigned all=(1u<<a.n)-1;const double metricScale=a.metric.cwiseAbs().maxCoeff();const Matrix reduced=a.metric/metricScale;Eigen::LLT<Matrix> llt(reduced);if(llt.info()!=Eigen::Success)throw Failure(PENTA_NUMERIC_ARGUMENT,"Hodge metric factorization failed.");const Matrix inverse=llt.solve(Matrix::Identity(a.n,a.n));long double volume=std::pow(static_cast<long double>(metricScale),static_cast<long double>(a.n)/2-a.k);for(unsigned axis=0;axis<a.n;++axis)volume*=llt.matrixL()(axis,axis);values.assign(output.size(),0);first.assign(output.size()*a.n,0);second.assign(output.size()*a.n*a.n,0);order=a.constant?2:0;
        for(std::size_t j=0;j<output.size();++j){const unsigned complement=all^output[j];std::vector<unsigned> rows;for(unsigned axis=0;axis<a.n;++axis)if(complement&(1u<<axis))rows.push_back(axis);for(std::size_t i=0;i<a.masks.size();++i){work.spend(std::max<unsigned>(1,a.k*a.k*a.k));std::vector<unsigned> columns;for(unsigned axis=0;axis<a.n;++axis)if(a.masks[i]&(1u<<axis))columns.push_back(axis);Eigen::Matrix<long double,Eigen::Dynamic,Eigen::Dynamic,Eigen::RowMajor> minor(a.k,a.k);for(unsigned r=0;r<a.k;++r)for(unsigned c=0;c<a.k;++c)minor(r,c)=inverse(rows[r],columns[c]);const long double determinant=a.k?minor.determinant():1;values[j]=finite(static_cast<long double>(values[j])+a.orientation*volume*sign(complement,output[j])*determinant*a.value[i]);}}
    }else if(request->operation!=PENTA_FORM_COPY)throw Failure(PENTA_NUMERIC_ARGUMENT,"Unknown differential-form operation.");
    if(values.size()>result->capacity||(!values.empty()&&!result->coefficients)||(order>=1&&!values.empty()&&!result->first)||(order>=2&&!values.empty()&&!result->second))throw Failure(PENTA_NUMERIC_ARGUMENT,"Differential-form output capacity is insufficient.");
    work.commit();if(!values.empty())std::copy(values.begin(),values.end(),result->coefficients);if(order>=1&&!first.empty())std::copy(first.begin(),first.end(),result->first);if(order>=2&&!second.empty())std::copy(second.begin(),second.end(),result->second);result->dimension=a.n;result->degree=degree;result->derivative_order=order;result->constant_coefficients=constant;result->count=values.size();result->work_units=work.used.load();return 0;
 }catch(const Failure& e){message(error,capacity,e.what());return e.status;}catch(const std::exception& e){message(error,capacity,e.what());return PENTA_NUMERIC_DOMAIN;}catch(...){message(error,capacity,"Unknown differential-form failure.");return PENTA_NUMERIC_INTERNAL;}
}
}
extern "C" int penta_extra_forms(const penta_geometry_extra_host_v1* host,const penta_form_request_v1* request,penta_form_result_v1* result,char* error,uint64_t capacity){return forms(host,request,result,error,capacity);}
extern "C" int penta_extra_laplace(const penta_chart_point_v1* chart,const double* first,const double* second,double* result,char* error,uint64_t capacity){
 try{using namespace penta::geometry_extra;if(!chart||chart->struct_size<sizeof(*chart)||chart->dimension<2||chart->dimension>5||!first||!second||!result)throw Failure(PENTA_NUMERIC_ARGUMENT,"Laplace-Beltrami requires a checked two-dimensional chart and native scalar gradient/Hessian.");long double value=0;for(unsigned a=0;a<2;++a)for(unsigned b=0;b<2;++b){if(!std::isfinite(chart->inverse_metric[a*2+b])||!std::isfinite(second[a*2+b]))throw Failure(PENTA_NUMERIC_ARGUMENT,"Nonfinite Laplace-Beltrami metric/Hessian.");long double covariant=second[a*2+b];for(unsigned c=0;c<2;++c){if(!std::isfinite(first[c])||!std::isfinite(chart->christoffel[c*4+a*2+b]))throw Failure(PENTA_NUMERIC_ARGUMENT,"Nonfinite Laplace-Beltrami connection/gradient.");covariant-=static_cast<long double>(chart->christoffel[c*4+a*2+b])*first[c];}value+=chart->inverse_metric[a*2+b]*covariant;}*result=finite(value);return 0;
 }catch(const penta::geometry_extra::Failure& e){penta::geometry_extra::message(error,capacity,e.what());return e.status;}catch(const std::exception& e){penta::geometry_extra::message(error,capacity,e.what());return PENTA_NUMERIC_DOMAIN;}
}
